"""soniox_websocket_transcriber: Real-time STT via Soniox WebSocket API.

Used when the API key is a short-lived demo key (starts with 'temp:').
Converts audio to PCM 16kHz mono, splits into silence-aware chunks (≤3.5s),
and streams all chunks in parallel — each over its own WebSocket session.

Why silence-aware chunks?
  Cutting at natural speech pauses keeps each session to a complete phrase/sentence,
  preserving context within the finalization window. Fixed-time cuts risk breaking
  mid-word or mid-sentence, degrading transcription accuracy.

Why leading context (_LEAD_SECS)?
  Each session includes 1s of audio from the PREVIOUS chunk before the actual content.
  The model transcribes that leading audio first, building language/speaker context,
  so when it reaches the actual content the BPE tokenizer flows naturally from prior
  speech — eliminating sub-word artifacts ("R Ờ", "th Họ") at session boundaries.
  Leading tokens are dropped from results; only the actual chunk portion is kept.

Why ≤3.5s content per session?
  Soniox demo keys finalize the first ~5s of tokens per WS session.
  With 1.0s lead + 3.5s content + 0.5s tail = 5.0s total — safely within the window.

Why parallel sessions?
  All micro-sessions run concurrently (bounded by _CONCURRENCY semaphore).
  For a 10-minute file (~170 chunks, concurrency=64): ~22s total — ~27× real-time.
"""
from __future__ import annotations

import asyncio
import json
import re
import subprocess
from typing import Any

from atcli.utils.logger import get_logger

logger = get_logger(__name__)

SONIOX_RT_URL = "wss://stt-rt.soniox.com/transcribe-websocket"
_PCM_SAMPLE_RATE = 16000
_PCM_CHANNELS = 1
_BYTES_PER_SEC = _PCM_SAMPLE_RATE * _PCM_CHANNELS * 2   # 32000 bytes/s for 16kHz mono s16le

# Chunk size for streaming (independent of segment size)
_CHUNK_BYTES = 8192

# Silence-aware segmentation settings.
_MAX_CHUNK_SECS = 3.5    # content limit: lead(1.0) + content(3.5) + tail(0.5) = 5.0s total
_MIN_CHUNK_SECS = 0.5    # ignore silences that would create chunks shorter than this
_SILENCE_DB = -40.0      # dB threshold — slightly more sensitive than -38 to find more cut points
_SILENCE_MIN_DUR = 0.1   # minimum silence duration (seconds) to count as a cut point

# Leading context: audio from previous chunk prepended to each session so the model has
# language/speaker context before transcribing new content. Leading tokens are dropped.
_LEAD_SECS = 1.0

# Retry empty sessions (network glitch, server overload) before giving up.
_SESSION_RETRIES = 2

# Tail overlap: extra audio past end_s so the last word before a hard-cut is fully heard.
_OVERLAP_SECS = 0.5

# Stream at 8× real-time (was 16×) — slightly more natural pace for the model
_STREAM_FACTOR = 8.0
_CHUNK_SLEEP_S = _CHUNK_BYTES / _BYTES_PER_SEC / _STREAM_FACTOR   # ~0.032s

# Timeouts
_FIRST_TOKEN_TIMEOUT_S = 10.0
_IDLE_TIMEOUT_S = 1.5

# Max concurrent WebSocket sessions.
# Benchmarks on 10-min audio: 16→54s, 32→28s, 64→17.5s (34×RT), 150→8.9s (quality drop).
# 64 is the sweet spot: consistent token count, no server overload.
_CONCURRENCY = 64


def transcribe_file_via_websocket(
    file_path: str,
    api_key: str,
    context: dict[str, Any] | None = None,
    language_hints: list[str] | None = None,
) -> list[dict[str, Any]]:
    """Transcribe a local audio file via Soniox real-time WebSocket API.

    Detects silence points and cuts at natural speech boundaries (≤5s per chunk).
    All chunks stream in parallel (up to _CONCURRENCY sessions). Tokens sorted
    by start_ms before returning.
    """
    logger.info("Converting audio to PCM for WebSocket streaming...")
    pcm_data = _to_pcm(file_path)
    total_secs = len(pcm_data) / _BYTES_PER_SEC

    logger.info("Detecting silence boundaries...")
    silence_ends = _detect_silence_points(file_path)
    chunks = _build_silence_chunks(total_secs, silence_ends)

    logger.info(
        "PCM ready: %.1f seconds — %d silence-aware chunks (lead=%.1fs), %d parallel sessions",
        total_secs, len(chunks), _LEAD_SECS, min(_CONCURRENCY, len(chunks)),
    )

    ws_context = _build_ws_context(context)
    hints = language_hints or ["en", "ja", "vi", "zh", "ko"]

    # Build jobs: (index, pcm_bytes, audio_offset_ms, lead_ms, boundary_ms, is_last)
    #   audio_offset_ms — absolute time where this audio clip starts (including lead)
    #   lead_ms         — ms of leading context at front of clip (drop these tokens)
    #   boundary_ms     — duration of actual chunk content (drop tail tokens beyond this)
    #   is_last         — last job keeps all tokens past lead (no successor covers the tail)
    last_idx = len(chunks) - 1
    jobs: list[tuple[int, bytes, int, int, int, bool]] = []
    for i, (start_s, end_s) in enumerate(chunks):
        # Leading context: include up to _LEAD_SECS of audio before this chunk
        audio_start_s = max(0.0, start_s - _LEAD_SECS)
        lead_secs = start_s - audio_start_s  # actual lead (< _LEAD_SECS near file start)

        # PCM s16le: 2 bytes per sample — byte offsets must be even-aligned.
        start_byte = (int(audio_start_s * _BYTES_PER_SEC) // 2) * 2
        end_byte = min((int((end_s + _OVERLAP_SECS) * _BYTES_PER_SEC) // 2) * 2, len(pcm_data))

        audio_offset_ms = int(audio_start_s * 1000)
        lead_ms = int(lead_secs * 1000)
        boundary_ms = int((end_s - start_s) * 1000)
        jobs.append((i, pcm_data[start_byte:end_byte], audio_offset_ms, lead_ms, boundary_ms, i == last_idx))

    all_tokens = asyncio.run(_stream_all_parallel(jobs, api_key, hints, ws_context))
    logger.info("WebSocket transcription complete: %d tokens", len(all_tokens))
    return all_tokens


# ── Silence detection & chunking ─────────────────────────────────────────────

def _detect_silence_points(file_path: str) -> list[float]:
    """Return sorted list of silence-end timestamps (seconds) via ffmpeg silencedetect."""
    af = f"silencedetect=noise={_SILENCE_DB}dB:d={_SILENCE_MIN_DUR}"
    result = subprocess.run(
        ["ffmpeg", "-i", file_path, "-af", af, "-f", "null", "-"],
        capture_output=True, text=True,
    )
    ends: list[float] = []
    for line in result.stderr.splitlines():
        m = re.search(r"silence_end:\s*([\d.]+)", line)
        if m:
            ends.append(float(m.group(1)))
    return sorted(ends)


def _build_silence_chunks(total_secs: float, silence_ends: list[float]) -> list[tuple[float, float]]:
    """Build (start, end) pairs cutting at silence points, max _MAX_CHUNK_SECS each.

    For each chunk, advance cursor to the last silence_end within
    [cursor + _MIN_CHUNK_SECS, cursor + _MAX_CHUNK_SECS]. Hard-cut if none found.
    """
    chunks: list[tuple[float, float]] = []
    cursor = 0.0

    while cursor < total_secs:
        target_max = min(cursor + _MAX_CHUNK_SECS, total_secs)

        # Find the last silence_end in the valid window
        best_cut: float | None = None
        for s in reversed(silence_ends):
            if s > target_max:
                continue
            if s - cursor >= _MIN_CHUNK_SECS:
                best_cut = s
                break

        end = best_cut if best_cut is not None else target_max
        chunks.append((cursor, end))
        cursor = end

    return chunks


# ── PCM conversion ────────────────────────────────────────────────────────────

def _to_pcm(file_path: str) -> bytes:
    """Run ffmpeg to extract PCM s16le 16kHz mono bytes from any audio/video."""
    result = subprocess.run(
        [
            "ffmpeg", "-i", file_path,
            "-ar", str(_PCM_SAMPLE_RATE),
            "-ac", str(_PCM_CHANNELS),
            "-f", "s16le",
            "-",
        ],
        capture_output=True,
        check=True,
    )
    return result.stdout


# ── Context mapping ───────────────────────────────────────────────────────────

def _build_ws_context(context: dict[str, Any] | None) -> dict[str, Any] | None:
    """Map async-API context keys → real-time API context keys.

    Async API:  {"text": "...", "terms": [...]}
    RT API:     {"domain": "..."}  — translation_terms causes HTTP 400
    """
    if not context:
        return None
    domain = context.get("text", "").strip()
    return {"domain": domain} if domain else None


# ── Token helpers ─────────────────────────────────────────────────────────────

def _tok_entry(tok: dict[str, Any]) -> dict[str, Any]:
    return {
        "text": tok.get("text", ""),
        "speaker": tok.get("speaker"),
        "language": tok.get("language"),
        "start_ms": tok.get("start_ms"),
        "end_ms": tok.get("end_ms"),
    }


# ── Parallel orchestrator ─────────────────────────────────────────────────────

async def _stream_all_parallel(
    jobs: list[tuple[int, bytes, int, int, int, bool]],
    api_key: str,
    language_hints: list[str],
    ws_context: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    """Run all chunk sessions concurrently, return tokens sorted by start_ms.

    jobs: list of (index, pcm_bytes, audio_offset_ms, lead_ms, boundary_ms, is_last)
    """
    sem = asyncio.Semaphore(_CONCURRENCY)
    done_count = 0

    async def _guarded(
        index: int, pcm: bytes, audio_offset_ms: int, lead_ms: int, boundary_ms: int, is_last: bool
    ) -> tuple[int, list[dict[str, Any]]]:
        nonlocal done_count
        async with sem:
            tokens: list[dict[str, Any]] = []
            for attempt in range(_SESSION_RETRIES + 1):
                try:
                    tokens = await _stream_session(pcm, api_key, language_hints, ws_context)
                    break
                except RuntimeError:
                    if attempt >= _SESSION_RETRIES:
                        raise
                    await asyncio.sleep(0.5)

            # Drop leading context tokens (covered by previous chunk) and tail overlap
            # tokens (covered by next chunk). For the last chunk keep everything after lead.
            if is_last:
                tokens = [t for t in tokens if (t.get("start_ms") or 0) >= lead_ms]
            else:
                cut_ms = lead_ms + boundary_ms
                tokens = [t for t in tokens if lead_ms <= (t.get("start_ms") or 0) < cut_ms]

            # Shift to absolute timeline: audio clip started at audio_offset_ms
            for tok in tokens:
                if tok["start_ms"] is not None:
                    tok["start_ms"] += audio_offset_ms
                if tok["end_ms"] is not None:
                    tok["end_ms"] += audio_offset_ms

            # Safety: at hard-cut boundaries the first kept token may lack a leading space.
            # (With proper silence cuts the lead provides full context; this catches edge cases.)
            if audio_offset_ms > 0 and tokens and tokens[0]["text"]:
                if not tokens[0]["text"].startswith(" "):
                    tokens[0]["text"] = " " + tokens[0]["text"]

            done_count += 1
            if done_count % 10 == 0 or done_count == len(jobs):
                logger.debug("Chunks done: %d/%d", done_count, len(jobs))
            return index, tokens

    results = await asyncio.gather(*[_guarded(i, pcm, off, lead, bnd, last) for i, pcm, off, lead, bnd, last in jobs])
    all_tokens = [tok for _, tokens in results for tok in tokens]
    all_tokens.sort(key=lambda t: (t.get("start_ms") or 0))
    return all_tokens


# ── Single micro-session ──────────────────────────────────────────────────────

async def _stream_session(
    pcm_data: bytes,
    api_key: str,
    language_hints: list[str],
    ws_context: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    """Open one WebSocket session, stream PCM, return final tokens.

    For ≤ 5s chunks the server finalizes all tokens before sending `finished`,
    so the non-final fallback is a safety net only — normally empty.
    """
    try:
        import websockets
    except ImportError as exc:
        raise RuntimeError("websockets library not found — run: pip install websockets") from exc

    config_msg: dict[str, Any] = {
        "api_key": api_key,
        "model": "stt-rt-v4",
        "audio_format": "pcm_s16le",
        "sample_rate": _PCM_SAMPLE_RATE,
        "num_channels": _PCM_CHANNELS,
        "language_hints": language_hints,
        "enable_speaker_diarization": True,
        "enable_language_identification": True,
    }
    if ws_context:
        config_msg["context"] = ws_context

    final_tokens: list[dict[str, Any]] = []
    pending_nonfinal: list[dict[str, Any]] = []

    async with websockets.connect(SONIOX_RT_URL, open_timeout=15) as ws:
        await ws.send(json.dumps(config_msg))
        send_done = asyncio.Event()

        async def _sender() -> None:
            for offset in range(0, len(pcm_data), _CHUNK_BYTES):
                await ws.send(pcm_data[offset : offset + _CHUNK_BYTES])
                await asyncio.sleep(_CHUNK_SLEEP_S)
            await ws.send(b"")  # EOF signal
            send_done.set()

        async def _receiver() -> None:
            nonlocal pending_nonfinal
            received_any = False
            while True:
                timeout = _IDLE_TIMEOUT_S if send_done.is_set() else _FIRST_TOKEN_TIMEOUT_S
                try:
                    raw = await asyncio.wait_for(ws.recv(), timeout=timeout)
                except asyncio.TimeoutError:
                    if not received_any:
                        logger.warning("No response from Soniox WS after %.0fs.", _FIRST_TOKEN_TIMEOUT_S)
                    break

                received_any = True
                data = json.loads(raw)

                if data.get("finished"):
                    break

                if "error_code" in data or data.get("error"):
                    code = data.get("error_code", 0)
                    if code == 408:
                        break
                    raise RuntimeError(
                        f"Soniox WS error {code}: {data.get('error_message', data)}"
                    )

                batch_nonfinal: list[dict[str, Any]] = []
                for tok in data.get("tokens", []):
                    if tok.get("text") in ("", "<end>", None):
                        continue
                    entry = _tok_entry(tok)
                    if tok.get("is_final"):
                        final_tokens.append(entry)
                    else:
                        batch_nonfinal.append(entry)

                if batch_nonfinal:
                    pending_nonfinal = batch_nonfinal

        await asyncio.gather(_sender(), _receiver())

    # Safety net: if any audio slipped past the finalization window, use non-final tokens
    if pending_nonfinal:
        last_end = max((t["end_ms"] or 0) for t in final_tokens) if final_tokens else 0
        extra = [t for t in pending_nonfinal if (t["start_ms"] or 0) >= last_end]
        if extra:
            logger.debug("Chunk: appending %d non-final fallback tokens.", len(extra))
            final_tokens.extend(extra)

    return final_tokens
